#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

static Node *root = NULL;
static int used = 0;
static int printed = 0;

static void bst_insert(long v) {
    if (used >= MAX_NODES) return;
    Node *n = malloc(sizeof(Node));
    if (!n) { perror("malloc"); exit(EXIT_FAILURE); }
    n->value = v; n->left = n->right = NULL;
    Node **p = &root;
    while (*p) {
        if (v < (*p)->value) p = &(*p)->left; else p = &(*p)->right;
    }
    *p = n; used++;
}

static void maybe_space(void) { if (printed) putchar(' '); else printed = 1; }

static void inorder(Node *n) { if (!n) return; inorder(n->left); maybe_space(); printf("%ld", n->value); inorder(n->right); }
static void preorder(Node *n) { if (!n) return; maybe_space(); printf("%ld", n->value); preorder(n->left); preorder(n->right); }
static void postorder(Node *n) { if (!n) return; postorder(n->left); postorder(n->right); maybe_space(); printf("%ld", n->value); }

static void free_tree(Node *n) { if (!n) return; free_tree(n->left); free_tree(n->right); free(n); }

int main(int argc, char **argv) {
    if (argc < 2) { puts("INVALID_MODE"); return 0; }
    const char *mode = argv[1];
    for (int i = 2; i < argc; ++i) {
        char *end; long v = strtol(argv[i], &end, 10);
        (void)end; bst_insert(v);
    }
    if (strcmp(mode, "in") == 0) {
        if (!root) puts("EMPTY"); else { printed = 0; inorder(root); putchar('\n'); }
    } else if (strcmp(mode, "pre") == 0) {
        if (!root) puts("EMPTY"); else { printed = 0; preorder(root); putchar('\n'); }
    } else if (strcmp(mode, "post") == 0) {
        if (!root) puts("EMPTY"); else { printed = 0; postorder(root); putchar('\n'); }
    } else {
        puts("INVALID_MODE");
    }
    free_tree(root);
    return 0;
}
